"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[59604],{96322:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"EnemyDeathVfxController","desc":"Plays the `EnemyCombatConfig.DEATH_VFX` burst where an `EnemyNPC`-tagged\\nmodel dies. Detection is the replicated Humanoid Health reaching 0, so it\\nneeds no packet and covers every enemy kind (void + Encounter). An\\nunkillable enemy (the planned Leviathan) never reaches 0 and never bursts.\\nNo template in ReplicatedStorage \u2192 no-op.","realm":["Client"],"source":{"line":12,"path":"src/StarterPlayer/StarterPlayerScripts/EnemyDeathVfxController.client.luau"}}')}}]);